/* global React, ReactDOM, TweaksPanel, useTweaks, TweakSection, TweakRadio, TweakToggle, TweakColor */
const { useState, useEffect, useMemo } = React;

const TWEAK_DEFAULTS = /*EDITMODE-BEGIN*/{
  "ember": "#ff7a1a",
  "snow": true,
  "flicker": true,
  "moonStyle": "carved"
}/*EDITMODE-END*/;

// ---------- ICON: Carved Pumpkin (varying difficulty) ----------
function PumpkinIcon({ difficulty = "green", size = 40, glow = false }) {
  // difficulty: green (1 eye), blue (2 eyes), black (2 eyes + nose), double (full grin)
  const id = React.useId();
  const eyeL = <polygon points="32,42 44,42 38,52" fill="#0a0512" />;
  const eyeR = <polygon points="56,42 68,42 62,52" fill="#0a0512" />;
  const nose = <polygon points="50,56 46,62 54,62" fill="#0a0512" />;
  const grin = (
    <path d="M28,68 L34,62 L40,68 L46,62 L52,68 L58,62 L64,68 L70,62 L72,72 L66,76 L60,72 L54,76 L48,72 L42,76 L36,72 L30,76 Z"
      fill="#0a0512" />
  );
  return (
    <svg viewBox="0 0 100 100" width={size} height={size} className="pumpkin-icon" style={{ filter: glow ? `drop-shadow(0 0 10px var(--glow))` : 'none' }}>
      <defs>
        <radialGradient id={`pg-${id}`} cx="50%" cy="55%" r="55%">
          <stop offset="0%" stopColor="#ffb347" />
          <stop offset="55%" stopColor="var(--ember)" />
          <stop offset="100%" stopColor="#a13800" />
        </radialGradient>
      </defs>
      {/* stem */}
      <path d="M48,16 C46,10 52,6 56,12 C58,16 54,22 50,22 Z" fill="#3d2412" />
      {/* body lobes */}
      <ellipse cx="22" cy="58" rx="18" ry="26" fill={`url(#pg-${id})`} opacity="0.85" />
      <ellipse cx="78" cy="58" rx="18" ry="26" fill={`url(#pg-${id})`} opacity="0.85" />
      <ellipse cx="50" cy="60" rx="32" ry="30" fill={`url(#pg-${id})`} />
      {/* ribs */}
      <path d="M50,30 Q42,60 50,90" stroke="#a13800" strokeWidth="1" fill="none" opacity="0.5" />
      <path d="M50,30 Q58,60 50,90" stroke="#a13800" strokeWidth="1" fill="none" opacity="0.5" />
      {/* faces */}
      {difficulty === "green" && <>{eyeL}</>}
      {difficulty === "blue" && <>{eyeL}{eyeR}</>}
      {difficulty === "black" && <>{eyeL}{eyeR}{nose}</>}
      {difficulty === "double" && <>{eyeL}{eyeR}{nose}{grin}</>}
    </svg>
  );
}

// ---------- HERO MOON (carved jack-o-lantern) ----------
function MoonPumpkin({ flicker, style }) {
  if (style === "plain") {
    return (
      <svg viewBox="0 0 200 200" className={`moon ${flicker ? "flicker" : ""}`}>
        <defs>
          <radialGradient id="moon-g" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#fff3d4" />
            <stop offset="60%" stopColor="#ffd089" />
            <stop offset="100%" stopColor="#c47a1a" />
          </radialGradient>
        </defs>
        <circle cx="100" cy="100" r="78" fill="url(#moon-g)" />
        <circle cx="78" cy="86" r="6" fill="#9c5b18" opacity="0.4" />
        <circle cx="120" cy="120" r="9" fill="#9c5b18" opacity="0.35" />
        <circle cx="135" cy="80" r="4" fill="#9c5b18" opacity="0.4" />
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 200 200" className={`moon ${flicker ? "flicker" : ""}`}>
      <defs>
        <radialGradient id="pmoon" cx="50%" cy="55%" r="55%">
          <stop offset="0%" stopColor="#ffd089" />
          <stop offset="50%" stopColor="var(--ember)" />
          <stop offset="100%" stopColor="#7a2900" />
        </radialGradient>
        <radialGradient id="ember-glow" cx="50%" cy="55%" r="40%">
          <stop offset="0%" stopColor="#fff3d4" stopOpacity="0.9" />
          <stop offset="100%" stopColor="#fff3d4" stopOpacity="0" />
        </radialGradient>
      </defs>
      {/* halo */}
      <circle cx="100" cy="100" r="98" fill="url(#ember-glow)" opacity="0.4" />
      {/* stem */}
      <path d="M96,28 C92,16 104,10 110,18 C115,26 106,38 100,38 Z" fill="#2a1a0c" />
      <path d="M104,22 C112,14 122,18 124,28" stroke="#2a1a0c" strokeWidth="3" fill="none" strokeLinecap="round" />
      {/* body */}
      <ellipse cx="60" cy="110" rx="38" ry="54" fill="url(#pmoon)" opacity="0.92" />
      <ellipse cx="140" cy="110" rx="38" ry="54" fill="url(#pmoon)" opacity="0.92" />
      <ellipse cx="100" cy="112" rx="62" ry="60" fill="url(#pmoon)" />
      {/* ribs */}
      <path d="M100,52 Q80,112 100,172" stroke="#7a2900" strokeWidth="1.5" fill="none" opacity="0.6" />
      <path d="M100,52 Q120,112 100,172" stroke="#7a2900" strokeWidth="1.5" fill="none" opacity="0.6" />
      <path d="M100,52 Q60,112 100,172" stroke="#7a2900" strokeWidth="1" fill="none" opacity="0.4" />
      <path d="M100,52 Q140,112 100,172" stroke="#7a2900" strokeWidth="1" fill="none" opacity="0.4" />
      {/* carved face — glowing cutouts */}
      <g style={{ filter: "drop-shadow(0 0 6px #fff3d4) drop-shadow(0 0 16px var(--glow))" }}>
        <polygon points="62,90 86,90 74,114" fill="#fff3d4" />
        <polygon points="138,90 114,90 126,114" fill="#fff3d4" />
        <polygon points="100,116 92,130 108,130" fill="#fff3d4" />
        <path d="M52,140 L66,128 L78,140 L90,128 L100,140 L110,128 L122,140 L134,128 L148,140 L142,156 L130,148 L118,156 L106,148 L94,156 L82,148 L70,156 L58,148 Z"
          fill="#fff3d4" />
      </g>
    </svg>
  );
}

// ---------- RIDGE SILHOUETTE ----------
function Ridges() {
  return (
    <svg className="ridges" viewBox="0 0 1600 600" preserveAspectRatio="none">
      {/* far ridge */}
      <path d="M0,420 L80,360 L180,400 L260,330 L360,380 L460,300 L580,360 L680,290 L800,340 L920,280 L1040,330 L1160,260 L1280,310 L1400,250 L1520,300 L1600,260 L1600,600 L0,600 Z"
        fill="#1c1029" opacity="0.7" />
      {/* mid ridge */}
      <path d="M0,500 L120,420 L220,470 L320,380 L440,440 L560,360 L680,420 L800,340 L920,400 L1040,330 L1160,390 L1280,310 L1400,370 L1520,320 L1600,380 L1600,600 L0,600 Z"
        fill="#0f0818" />
      {/* near ridge with snow caps */}
      <path d="M0,580 L60,540 L140,560 L220,500 L320,540 L440,480 L560,520 L680,460 L800,500 L920,440 L1040,490 L1160,430 L1280,480 L1400,420 L1520,470 L1600,430 L1600,600 L0,600 Z"
        fill="#08030f" />
      {/* snow line on near ridge */}
      <path d="M210,505 L220,500 L235,508 M315,545 L320,540 L335,548 M435,485 L440,480 L455,488 M555,525 L560,520 L575,528 M675,465 L680,460 L695,468 M795,505 L800,500 L815,508 M915,445 L920,440 L935,448 M1035,495 L1040,490 L1055,498 M1155,435 L1160,430 L1175,438 M1275,485 L1280,480 L1295,488 M1395,425 L1400,420 L1415,428"
        stroke="#f5ecd9" strokeWidth="2" fill="none" opacity="0.7" strokeLinecap="round" />
      {/* tiny lift cable */}
      <line x1="100" y1="550" x2="1500" y2="380" stroke="#f5ecd9" strokeWidth="0.4" opacity="0.25" strokeDasharray="3,8" />
      {/* tiny pumpkin lift chairs */}
      {[200, 380, 560, 740, 920, 1100, 1280].map((x, i) => {
        const y = 550 + (380 - 550) * (x - 100) / 1400;
        return (
          <g key={i} transform={`translate(${x},${y - 12})`}>
            <line x1="0" y1="-10" x2="0" y2="0" stroke="#f5ecd9" strokeWidth="0.6" opacity="0.4" />
            <circle cx="0" cy="4" r="3" fill="var(--ember)" opacity="0.85" />
          </g>
        );
      })}
    </svg>
  );
}

// ---------- SNOW ----------
function Snow({ count = 60 }) {
  const flakes = useMemo(() => Array.from({ length: count }, (_, i) => ({
    left: Math.random() * 100,
    delay: Math.random() * 16,
    dur: 12 + Math.random() * 18,
    size: 1 + Math.random() * 3,
    op: 0.3 + Math.random() * 0.5,
  })), [count]);
  return (
    <div className="snow">
      {flakes.map((f, i) => (
        <span key={i} className="flake" style={{
          left: `${f.left}%`,
          animationDelay: `-${f.delay}s`,
          animationDuration: `${f.dur}s`,
          width: `${f.size}px`,
          height: `${f.size}px`,
          opacity: f.op
        }} />
      ))}
    </div>
  );
}

// ---------- TICKER ----------
function Ticker() {
  const items = [
    ["NEW SNOW 24H", "11\""],
    ["BASE", "82\""],
    ["LIFTS OPEN", "9 / 12"],
    ["TEMP", "28°F"],
    ["WIND SUMMIT", "14 MPH NW"],
    ["VISIBILITY", "MIST"],
    ["WITCHING HOUR", "4:42 PM"],
    ["MOONRISE", "5:18 PM"],
    ["TONIGHT", "TORCH-LIT DESCENT"],
    ["FOG DENSITY", "MODERATE"],
  ];
  const row = (
    <>{items.map(([k, v], i) => (
      <span key={i}>{k} <b>{v}</b><span className="sep">/ /</span></span>
    ))}</>
  );
  return (
    <div className="ticker">
      <div className="ticker-track">{row}{row}</div>
    </div>
  );
}

// ---------- CONDITIONS ----------
function Conditions() {
  const data = [
    { l: "FRESH SNOW · 24H", v: "11", u: '"', d: "+3\" since dusk" },
    { l: "PUMPKIN PATCH BASE", v: "82", u: '"', d: "groomed overnight" },
    { l: "LIFTS HAUNTING", v: "9", u: "/12", d: "Crone's Crest opens 10am" },
    { l: "SUMMIT TEMP", v: "28", u: "°F", d: "feels like 19°F", cool: true },
  ];
  return (
    <section className="block" data-screen-label="03 Conditions">
      <div className="container">
        <div className="section-head">
          <div>
            <div className="eyebrow">§ 01 — Tonight on the mountain</div>
            <h2 style={{ marginTop: 14 }}>The hollow is <em>open.</em></h2>
          </div>
          <p className="lede">Reports filed by the lift crew at last bell. Snowmaking runs from sunset to the witching hour; expect groomed corduroy under a candle-lit moon.</p>
        </div>
        <div className="cond-grid">
          {data.map((d, i) => (
            <div className="cond" key={i}>
              <div className="label">{d.l}</div>
              <div>
                <div className="value">{d.v}<sup>{d.u}</sup></div>
                <div className={`delta ${d.cool ? "cool" : ""}`} style={{ marginTop: 8 }}>{d.d}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

// ---------- TRAIL MAP ----------
const TRAILS = [
  { id: "t1", name: "Lantern Lane", diff: "green", level: "Beginner", vert: "412 ft", note: "Lit by 200 hand-carved gourds", x: 150, y: 380 },
  { id: "t2", name: "Goblin's Gully", diff: "blue", level: "Intermediate", vert: "880 ft", note: "Tree run. Hear the trees back.", x: 280, y: 280 },
  { id: "t3", name: "Witch's Knoll", diff: "blue", level: "Intermediate", vert: "1,040 ft", note: "Mogul field at moonset", x: 420, y: 220 },
  { id: "t4", name: "Headless Hollow", diff: "black", level: "Advanced", vert: "1,620 ft", note: "Steep glade. Bring a head.", x: 540, y: 160 },
  { id: "t5", name: "Banshee Bowl", diff: "black", level: "Advanced", vert: "1,840 ft", note: "Wide open. Wind sings through.", x: 360, y: 130 },
  { id: "t6", name: "Crone's Crest", diff: "double", level: "Expert", vert: "2,210 ft", note: "Cliffs, chutes, no second chances", x: 200, y: 100 },
];
function TrailMap() {
  const [active, setActive] = useState("t4");
  return (
    <section className="block" data-screen-label="04 Trails">
      <div className="container">
        <div className="section-head">
          <div>
            <div className="eyebrow">§ 02 — The Map</div>
            <h2 style={{ marginTop: 14 }}>Six runs.<br /><em>Each one carved.</em></h2>
          </div>
          <p className="lede">Difficulty marked the old way — by the face the mountain shows you. One eye for an easy night out. A full grin if you're not coming back the same.</p>
        </div>
        <div className="trail-wrap">
          <div className="trail-map">
            <svg viewBox="0 0 700 500" preserveAspectRatio="xMidYMid meet">
              <defs>
                <pattern id="dots" width="14" height="14" patternUnits="userSpaceOnUse">
                  <circle cx="1" cy="1" r="0.6" fill="#1c1029" />
                </pattern>
              </defs>
              <rect width="700" height="500" fill="url(#dots)" />
              {/* mountain contours */}
              <path d="M50,460 L120,400 L200,380 L260,300 L320,260 L380,200 L420,140 L470,100 L520,140 L560,200 L600,260 L650,340 L680,420" stroke="#1c1029" strokeWidth="1.5" fill="none" />
              <path d="M80,440 L160,360 L240,300 L320,220 L400,160 L470,120 L540,180 L620,280 L670,400" stroke="#1c1029" strokeWidth="1" fill="none" />
              <path d="M120,400 L220,340 L300,260 L380,180 L460,140 L540,200" stroke="#1c1029" strokeWidth="0.8" fill="none" />
              {/* trail lines */}
              {TRAILS.map(t => {
                const lift = { x: 470, y: 100 };
                const colors = { green:"#37d27e", blue:"#7ed1ff", black:"#bdb09a", double:"#ff7a1a" };
                return (
                  <path key={`p-${t.id}`}
                    d={`M${lift.x},${lift.y} Q${(lift.x+t.x)/2 + (t.id==='t6'?-60:30)},${(lift.y+t.y)/2 - 20} ${t.x},${t.y}`}
                    stroke={colors[t.diff]} strokeWidth={active===t.id?2.5:1.2} fill="none"
                    opacity={active===t.id?1:0.5} strokeDasharray={t.diff==='double'?'2,3':'none'}
                    style={{ transition: 'all .25s' }} />
                );
              })}
              {/* lift cable */}
              <line x1="600" y1="420" x2="470" y2="100" stroke="#f5ecd9" strokeWidth="0.6" opacity="0.3" strokeDasharray="2,4" />
              {/* base lodge */}
              <g transform="translate(580,400)">
                <rect x="-14" y="-10" width="28" height="20" fill="#14091f" stroke="#f5ecd9" strokeWidth="0.8" />
                <polygon points="-16,-10 16,-10 0,-22" fill="#f5ecd9" opacity="0.8" />
                <text x="0" y="32" fontFamily="JetBrains Mono" fontSize="9" fill="#6b5d76" textAnchor="middle" letterSpacing="2">BASE LODGE</text>
              </g>
              {/* summit */}
              <g transform="translate(470,100)">
                <text x="0" y="-30" fontFamily="JetBrains Mono" fontSize="9" fill="#ff7a1a" textAnchor="middle" letterSpacing="2">SUMMIT · 9,840 FT</text>
                <line x1="0" y1="-20" x2="0" y2="-2" stroke="#ff7a1a" strokeWidth="1" />
              </g>
              {/* trail markers */}
              {TRAILS.map(t => (
                <g key={t.id} transform={`translate(${t.x},${t.y})`} style={{ cursor: 'pointer' }} onMouseEnter={() => setActive(t.id)}>
                  <circle r={active === t.id ? 18 : 14} fill="#08030f" stroke={active === t.id ? "#ff7a1a" : "#6b5d76"} strokeWidth={active === t.id ? 1.5 : 0.8} />
                  <foreignObject x="-12" y="-12" width="24" height="24">
                    <PumpkinIcon difficulty={t.diff} size={24} glow={active === t.id} />
                  </foreignObject>
                  <text x="0" y="-22" fontFamily="Cinzel" fontSize="11" fill={active === t.id ? "#ff7a1a" : "#bdb09a"} textAnchor="middle" fontWeight="600">{t.name}</text>
                </g>
              ))}
            </svg>
          </div>
          <div className="trail-list">
            {TRAILS.map(t => (
              <div key={t.id} className={`trail ${active === t.id ? "active" : ""}`} onMouseEnter={() => setActive(t.id)}>
                <PumpkinIcon difficulty={t.diff} size={40} glow={active === t.id} />
                <div>
                  <div className="name">{t.name}</div>
                  <div className="meta">{t.level} · {t.note}</div>
                </div>
                <div className="vert">{t.vert}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

// ---------- LODGES ----------
function Lodges() {
  const lodges = [
    {
      tag: "001 · CABIN",
      name: "The Hollow",
      desc: "A one-bedroom timber cabin tucked into the spruce. Wood stove, copper kettle, and a porch that faces the moon.",
      feats: ["Sleeps 2", "Stone hearth", "Ski-in", "Pumpkin spiced"],
      price: 348,
      angle: 12,
    },
    {
      tag: "002 · SUITE",
      name: "Crow's Roost",
      desc: "Top-floor suite at the main lodge with a turret reading nook and a clawfoot tub. Gargoyle on the balcony, friendly.",
      feats: ["Sleeps 4", "Soaking tub", "Lift view", "Turret"],
      price: 612,
      angle: -8,
    },
    {
      tag: "003 · CHALET",
      name: "The Coven",
      desc: "Six-bedroom slope-side chalet for a proper gathering. Private chef, hot spring, and a cellar of mulled cider.",
      feats: ["Sleeps 12", "Hot spring", "Private chef", "Cellar"],
      price: 1840,
      angle: 6,
    },
  ];
  return (
    <section className="block" data-screen-label="05 Lodging">
      <div className="container">
        <div className="section-head">
          <div>
            <div className="eyebrow">§ 03 — Where you'll sleep (or won't)</div>
            <h2 style={{ marginTop: 14 }}>Three lodgings,<br /><em>each haunted differently.</em></h2>
          </div>
          <p className="lede">Every key comes with a candle, a tin of cider, and the name of whoever stayed in the room before you. Most reviews are favorable.</p>
        </div>
        <div className="lodges">
          {lodges.map((l, i) => (
            <article className="lodge" key={i}>
              <div className="img" style={{ background: i === 0
                ? "radial-gradient(circle at 30% 30%, #2a1a3a, #08030f), repeating-linear-gradient(45deg,#1c1029 0 12px,#150b22 12px 24px)"
                : i === 1
                ? "radial-gradient(circle at 70% 40%, #3a2a4a, #08030f), repeating-linear-gradient(135deg,#1c1029 0 16px,#150b22 16px 32px)"
                : "radial-gradient(circle at 50% 60%, #4a2a3a, #08030f), repeating-linear-gradient(90deg,#1c1029 0 20px,#150b22 20px 40px)" }}>
                {/* small pumpkin in corner */}
                <div style={{ position: 'absolute', top: 18, right: 18, transform: `rotate(${l.angle}deg)` }}>
                  <PumpkinIcon difficulty={["green","blue","black"][i]} size={56} glow />
                </div>
                <span className="tag">{l.tag}</span>
              </div>
              <div className="body">
                <h3>{l.name}</h3>
                <p>{l.desc}</p>
                <div className="feat">{l.feats.map(f => <span key={f}>{f}</span>)}</div>
                <div className="price">
                  <div className="amt">${l.price}<sup>/night</sup></div>
                  <div className="per">3-night<br />minimum</div>
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

// ---------- EVENTS ----------
function Events() {
  const evs = [
    { date: "OCT 31", day: "31", title: "Torch-lit Descent", desc: "After last lift, ski instructors lead a serpentine descent of Lantern Lane carrying iron torches. Cider at the bottom.", tag: "Nightly · 7:00 PM" },
    { date: "NOV 02", day: "02", title: "Carving on the Quad", desc: "Bring your gourd. We'll lift you to the summit, give you a knife, and a chair on the way down to carve.", tag: "Reservations" },
    { date: "NOV 09", day: "09", title: "Costume Slalom", desc: "Race the gates in full regalia. Ghosts get a 1.5-second handicap. Witches over 200 years old race for free.", tag: "Open enroll" },
    { date: "NOV 16", day: "16", title: "Bonfire & Banshee", desc: "Storyteller Margery Hollow tells true accounts from the back side of Banshee Bowl while the fire dies.", tag: "Free · Cider extra" },
  ];
  return (
    <section className="block" data-screen-label="06 Events">
      <div className="container">
        <div className="section-head">
          <div>
            <div className="eyebrow">§ 04 — The season calendar</div>
            <h2 style={{ marginTop: 14 }}>Things to do <em>after dark.</em></h2>
          </div>
          <p className="lede">Hollow's Edge runs October through whenever the moon stops cooperating. Below: the four most-asked-about evenings on the calendar.</p>
        </div>
        <div className="events">
          {evs.map((e, i) => (
            <div className="event" key={i}>
              <div className="when">{e.date.split(" ")[0]}<span className="day">{e.day}</span></div>
              <div>
                <h4>{e.title}</h4>
                <p>{e.desc}</p>
                <span className="tag">{e.tag}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

// ---------- BOOKING ----------
function Booking() {
  const [arrive, setArrive] = useState("2026-10-31");
  const [depart, setDepart] = useState("2026-11-03");
  const [guests, setGuests] = useState(2);
  const [lodge, setLodge] = useState("hollow");
  const lodges = { hollow: { name: "The Hollow", price: 348 }, roost: { name: "Crow's Roost", price: 612 }, coven: { name: "The Coven", price: 1840 } };

  const nights = useMemo(() => {
    const a = new Date(arrive), d = new Date(depart);
    return Math.max(1, Math.round((d - a) / (1000 * 60 * 60 * 24)));
  }, [arrive, depart]);
  const sub = lodges[lodge].price * nights;
  const lift = guests * 145 * nights;
  const tax = Math.round((sub + lift) * 0.094);
  const total = sub + lift + tax;
  const fmt = n => n.toLocaleString("en-US");

  return (
    <section className="block" data-screen-label="07 Booking" style={{ borderBottom: "none" }}>
      <div className="container">
        <div className="section-head">
          <div>
            <div className="eyebrow">§ 05 — Reserve your hex</div>
            <h2 style={{ marginTop: 14 }}>Pick a night.<br /><em>The mountain will know.</em></h2>
          </div>
          <p className="lede">No deposit holds the booking past the new moon. Cancel up to 72 hours before arrival; after that, the spirits keep half.</p>
        </div>
        <div className="book-wrap">
          <div className="book-quote">
            <div className="label">Reservation</div>
            <div className="book-grid">
              <label className="field">
                <span className="k">Arrive</span>
                <input type="date" value={arrive} onChange={e => setArrive(e.target.value)} />
              </label>
              <label className="field">
                <span className="k">Depart</span>
