          </div>

          <div>
            <div style={{ fontFamily: "Cinzel, serif", fontSize: 36, lineHeight: 1.1, marginBottom: 24 }}>
              "The first time I came I stayed three nights. <em style={{ color: "var(--ember)" }}>I've come back every Halloween for nine years.</em>"
            </div>
            <div style={{ fontFamily: "JetBrains Mono, monospace", fontSize: 11, color: "var(--fog)", letterSpacing: ".14em", textTransform: "uppercase" }}>— Iris H., Asheville · Frequent Wraith</div>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 16, marginTop: 56, paddingTop: 32, borderTop: "1px solid var(--line)" }}>
              {[["1,840", "VERTICAL FT"], ["72", "AVG SEASON DAYS"], ["1923", "ESTABLISHED"]].map(([v, k]) => (
                <div key={k}>
                  <div style={{ fontFamily: "Cinzel, serif", fontSize: 40, color: "var(--ghost)", lineHeight: 1 }}>{v}</div>
                  <div style={{ fontFamily: "JetBrains Mono, monospace", fontSize: 10, color: "var(--fog)", letterSpacing: ".16em", textTransform: "uppercase", marginTop: 8 }}>{k}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

