// ---------- APP ----------
function App() {
  const { tweaks, setTweak } = useTweaks(TWEAK_DEFAULTS);

  useEffect(() => {
    document.documentElement.style.setProperty("--ember", tweaks.ember);
    // glow auto-derives lighter
    const g = tweaks.ember === "#ff7a1a" ? "#ffb347"
      : tweaks.ember === "#7e6bff" ? "#a99dff"
      : tweaks.ember === "#e23b4b" ? "#ff7d8a"
      : "#ffb347";
    document.documentElement.style.setProperty("--glow", g);
  }, [tweaks.ember]);

  return (
    <>
      <Nav />
      <Hero snow={tweaks.snow} flicker={tweaks.flicker} moonStyle={tweaks.moonStyle} />
      <Ticker />
      <Conditions />
      <TrailMap />
      <Lodges />
      <Events />
      <Booking />
      <Footer />

      <TweaksPanel tweaks={tweaks}>
        <TweakSection title="Ember Palette">
          <TweakColor label="Accent" value={tweaks.ember} onChange={v => setTweak("ember", v)}
            options={["#ff7a1a", "#7e6bff", "#e23b4b"]} />
        </TweakSection>
        <TweakSection title="Atmosphere">
          <TweakToggle label="Snowfall" value={tweaks.snow} onChange={v => setTweak("snow", v)} />
          <TweakToggle label="Pumpkin flicker" value={tweaks.flicker} onChange={v => setTweak("flicker", v)} />
          <TweakRadio label="Moon" value={tweaks.moonStyle}
            onChange={v => setTweak("moonStyle", v)}
            options={[{ label: "Carved", value: "carved" }, { label: "Plain", value: "plain" }]} />
        </TweakSection>
      </TweaksPanel>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

